function cleanHtml(rawText) {
  if (!rawText || typeof rawText !== 'string') return '';
  let text = rawText.replace(/<[^>]*>/g, ' ');
  const entities = {
    '&amp;': '&', '&lt;': '<', '&gt;': '>', '&quot;': '"', '&#39;': "'",
    '&apos;': "'", '&#8377;': '₹', '&nbsp;': ' ', '&#160;': ' ',
    '&ndash;': '–', '&mdash;': '—', '&rsquo;': "'", '&lsquo;': "'",
    '&rdquo;': '"', '&ldquo;': '"'
  };
  for (const [entity, char] of Object.entries(entities)) {
    text = text.split(entity).join(char);
  }
  return text.replace(/\s+/g, ' ').trim();
}

function cleanUrl(rawUrl) {
  if (!rawUrl || typeof rawUrl !== 'string') return '';
  try {
    const parsed = new URL(rawUrl.trim());
    ['utm_source', 'utm_medium', 'utm_campaign', 'ref', 'source'].forEach(p => parsed.searchParams.delete(p));
    return parsed.toString();
  } catch {
    return rawUrl.trim();
  }
}

const normalizedItems = [];
for (const item of $input.all()) {
  const data = item.json || {};
  const rawTitle = data.title || data['atom:title'] || data.headline || '';
  const title = cleanHtml(typeof rawTitle === 'object' ? rawTitle._ || rawTitle['#text'] || '' : rawTitle);
  if (!title || title.length < 5) continue;

  const rawDesc = data.description || data.contentSnippet || data.summary || '';
  const description = cleanHtml(typeof rawDesc === 'object' ? rawDesc._ || rawDesc['#text'] || '' : rawDesc);
  const rawUrl = data.link || data.url || data.guid || '';
  const url = cleanUrl(typeof rawUrl === 'object' ? rawUrl._ : rawUrl);

  const source = data.source || (url.includes('thehindu.com') ? 'The Hindu' : (url.includes('pib.gov.in') ? 'PIB' : (url.includes('rbi.org.in') ? 'RBI' : (url.includes('prd.kerala.gov.in') ? 'PRD Kerala' : 'Official Source'))));
  const isPrimary = source.toLowerCase().includes('the hindu');
  const category = data.category || (Array.isArray(data.categories) ? data.categories[0] : '') || 'General';

  normalizedItems.push({
    json: {
      title,
      description: description.substring(0, 1000),
      url,
      source,
      isPrimary,
      category: typeof category === 'string' ? category : 'General',
      publishedAt: data.pubDate || data.isoDate || new Date().toISOString()
    }
  });
}
return normalizedItems;

const ACRONYM_MAP = {
  'rbi': 'reserve bank india', 'isro': 'indian space research organisation',
  'drdo': 'defence research development organisation', 'sc': 'supreme court',
  'hc': 'high court', 'pm': 'prime minister', 'cm': 'chief minister',
  'mpc': 'monetary policy committee', 'upsc': 'union public service commission',
  'psc': 'public service commission', 'kpsc': 'kerala public service commission',
  'gdp': 'gross domestic product', 'cpi': 'consumer price index', 'sebi': 'securities exchange board india'
};

const STOP_WORDS = new Set([
  'a', 'an', 'the', 'and', 'or', 'in', 'on', 'at', 'to', 'for', 'of', 'with', 'by',
  'from', 'as', 'is', 'are', 'was', 'were', 'be', 'been', 'being', 'have', 'has',
  'had', 'do', 'does', 'did', 'will', 'would', 'shall', 'should', 'can', 'could',
  'it', 'its', 'itself', 'new', 'after', 'over', 'into', 'under', 'says', 'said',
  'holds', 'keeps', 'retains', 'announces', 'unveils', 'launches', 'sets'
]);

function tokenizeAndExpand(title) {
  if (!title) return new Set();
  let text = title.toLowerCase().replace(/[^a-z0-9\s]/g, ' ');
  for (const [acronym, exp] of Object.entries(ACRONYM_MAP)) {
    text = text.replace(new RegExp(`\\b${acronym}\\b`, 'g'), exp);
  }
  return new Set(text.split(/\s+/).filter(w => w.length > 1 && !STOP_WORDS.has(w)));
}

function calculateSimilarity(setA, setB) {
  if (setA.size === 0 || setB.size === 0) return 0;
  let intersection = 0;
  for (const t of setA) if (setB.has(t)) intersection++;
  const containment = intersection / Math.min(setA.size, setB.size);
  const dice = (2 * intersection) / (setA.size + setB.size);
  return Math.max(containment, dice);
}

const inputItems = $input.all().map(i => i.json);
const uniqueStories = [];
const seenUrls = new Set();

for (const item of inputItems) {
  if (!item.title || !item.url || seenUrls.has(item.url)) continue;
  const currentTokens = tokenizeAndExpand(item.title);
  let duplicateIndex = -1;
  for (let i = 0; i < uniqueStories.length; i++) {
    if (calculateSimilarity(currentTokens, uniqueStories[i]._tokens) >= 0.55) {
      duplicateIndex = i;
      break;
    }
  }
  if (duplicateIndex === -1) {
    seenUrls.add(item.url);
    uniqueStories.push({
      ...item,
      supportingSources: [],
      _tokens: currentTokens
    });
  } else {
    const existing = uniqueStories[duplicateIndex];
    if (item.isPrimary && !existing.isPrimary) {
      existing.supportingSources.push({
        source: existing.source, url: existing.url, title: existing.title, publishedAt: existing.publishedAt
      });
      existing.title = item.title;
      existing.description = item.description || existing.description;
      existing.url = item.url;
      existing.source = item.source;
      existing.isPrimary = true;
      existing.category = item.category || existing.category;
      existing.publishedAt = item.publishedAt;
      existing._tokens = currentTokens;
      seenUrls.add(item.url);
    } else {
      existing.supportingSources.push({
        source: item.source, url: item.url, title: item.title, publishedAt: item.publishedAt
      });
      seenUrls.add(item.url);
    }
  }
}
return uniqueStories.map(s => { const { _tokens, ...clean } = s; return { json: clean }; });

const items = $input.all().map(i => i.json);
return [{
  json: {
    itemsCount: items.length,
    items: items.map((item, idx) => ({
      id: idx + 1,
      title: item.title,
      description: item.description,
      source: item.source,
      url: item.url,
      category: item.category,
      supportingSources: item.supportingSources || []
    }))
  }
}];

const response = $input.first().json.text || $input.first().json.response || '';
let parsed = {};
try {
  const cleanJson = response.replace(/^```[a-z]*\n?/i, '').replace(/\n?```$/i, '').trim();
  parsed = JSON.parse(cleanJson);
} catch (err) {
  const match = response.match(/\{[\s\S]*\}/);
  if (match) {
    try { parsed = JSON.parse(match[0]); } catch (e) { parsed = { stories: [] }; }
  } else {
    parsed = { stories: [] };
  }
}
const stories = parsed.stories || [];
return [{
  json: {
    date: new Date().toISOString().split('T')[0],
    stories: stories.map((s, idx) => ({
      rank: idx + 1,
      title: s.title || 'Untitled Story',
      category: s.category || 'National',
      source: s.source || 'The Hindu',
      url: s.url || '',
      supportingSources: s.supportingSources || [],
      whyImportant: s.whyImportant || '',
      targetExams: s.targetExams || ['Kerala PSC', 'SSC', 'UPSC', 'Banking'],
      confidence: s.confidence || 0.95
    }))
  }
}];

const response = $input.first().json.text || $input.first().json.response || '';
let parsed = {};
try {
  parsed = JSON.parse(response.replace(/^```[a-z]*\n?/i, '').replace(/\n?```$/i, '').trim());
} catch (e) {
  parsed = { researchedStories: [] };
}

const stories = parsed.researchedStories || [];
const MIN_CONF = 0.85;
let manualCheckCount = 0;

const processed = stories.map((s, idx) => {
  const conf = typeof s.confidence === 'number' ? s.confidence : parseFloat(s.confidence) || 0.9;
  const isVerified = s.verified !== false && conf >= MIN_CONF;
  if (!isVerified) manualCheckCount++;
  return {
    ...s,
    rank: idx + 1,
    confidence: conf,
    verified: isVerified,
    needsManualCheck: !isVerified,
    verificationBadge: isVerified ? '✅ VERIFIED' : '⚠️ MANUAL_VERIFICATION_REQUIRED'
  };
});

return [{
  json: {
    date: new Date().toISOString().split('T')[0],
    stories: processed,
    stats: {
      totalStories: processed.length,
      verifiedCount: processed.length - manualCheckCount,
      manualCheckCount
    }
  }
}];

parameters.prompt:
=Generate 15 high-yield MCQs (Kerala PSC, SSC, UPSC, Banking) with 4 options (A,B,C,D), correct answer, and explanation based on:

{{ JSON.stringify($json.stories) }}

Return JSON: {"mcqs": [{"id": 1, "question": "...", "options": {"A": "...", "B": "...", "C": "...", "D": "..."}, "correctAnswer": "A", "explanation": "..."}]}

=Extract 5 competitive-exam English vocabulary words from today's current affairs with Part of speech, English meaning, Malayalam meaning, synonyms, antonym, and example sentence based on:

{{ JSON.stringify($json.stories) }}

Return JSON: {"vocabulary": [{"word": "...", "partOfSpeech": "...", "englishMeaning": "...", "malayalamMeaning": "...", "synonyms": ["..."], "antonym": "...", "exampleSentence": "..."}]}

=Write an 8-12 minute Malayalam YouTube voice-over script across all 12 sections (Intro, National, Kerala, International, Economy, Sci-Tech, Environment, Defence, Appointments, Vocabulary, MCQ revision, Outro) based on:

