Return clean markdown voice-over script in spoken Malayalam.

parameters.jsCode:
const malayalamRes = $('Malayalam Explanations').first().json.text || '';
const mcqsRes = $('Exam MCQs Generator').first().json.text || '';
const vocabRes = $('Exam Vocabulary Generator').first().json.text || '';
const ytScript = $('YouTube Script Generator').first().json.text || '';
const baseData = $('Confidence Gate Evaluator').first().json || {};

let malayalamStories = [];
try { malayalamStories = JSON.parse(malayalamRes.replace(/^```[a-z]*\n?/i, '').replace(/\n?```$/i, '').trim()).storiesWithMalayalam || []; } catch (e) {}

let mcqs = [];
try { mcqs = JSON.parse(mcqsRes.replace(/^```[a-z]*\n?/i, '').replace(/\n?```$/i, '').trim()).mcqs || []; } catch (e) {}

let vocabulary = [];
try { vocabulary = JSON.parse(vocabRes.replace(/^```[a-z]*\n?/i, '').replace(/\n?```$/i, '').trim()).vocabulary || []; } catch (e) {}

const combinedStories = (baseData.stories || []).map((s, idx) => {
  const mal = malayalamStories[idx] || {};
  return {
    ...s,
    malayalamExplanation: mal.malayalamExplanation || mal.explanation || null
  };
});

return [{
  json: {
    date: baseData.date || new Date().toISOString().split('T')[0],
    stories: combinedStories,
    vocabulary,
    mcqs,
    youtubeScript: ytScript,
    summaryStats: baseData.stats || { totalStories: combinedStories.length, manualCheckCount: 0, verifiedCount: combinedStories.length }
  }
}];

const payload = $input.first().json || {};
const dateStr = payload.date || new Date().toISOString().split('T')[0];
const stories = payload.stories || [];
const vocabulary = payload.vocabulary || [];
const mcqs = payload.mcqs || [];
const youtubeScript = payload.youtubeScript || '';
const stats = payload.summaryStats || { totalStories: stories.length, verifiedCount: stories.length, manualCheckCount: 0 };

const categories = {
  'NATIONAL': [], 'KERALA': [], 'INTERNATIONAL': [], 'ECONOMY & BANKING': [],
  'SCIENCE & TECHNOLOGY': [], 'ENVIRONMENT': [], 'DEFENCE': [], 'AWARDS & APPOINTMENTS': [], 'OTHER': []
};

for (const s of stories) {
  const cat = (s.category || '').toUpperCase();
  if (cat.includes('KERALA')) categories['KERALA'].push(s);
  else if (cat.includes('INTERNATION')) categories['INTERNATIONAL'].push(s);
  else if (cat.includes('ECONOM') || cat.includes('BANK')) categories['ECONOMY & BANKING'].push(s);
  else if (cat.includes('SCI') || cat.includes('TECH') || cat.includes('SPACE')) categories['SCIENCE & TECHNOLOGY'].push(s);
  else if (cat.includes('ENVIRON')) categories['ENVIRONMENT'].push(s);
  else if (cat.includes('DEFEN')) categories['DEFENCE'].push(s);
  else if (cat.includes('AWARD') || cat.includes('APPOINT')) categories['AWARDS & APPOINTMENTS'].push(s);
  else if (cat.includes('NATION') || cat.includes('POLIC') || cat.includes('LEGAL')) categories['NATIONAL'].push(s);
  else categories['OTHER'].push(s);
}

let md = `# DAILY CURRENT AFFAIRS\n`;
md += `**Date:** ${dateStr}\n\n`;
md += `**Primary Source:** The Hindu\n`;
md += `**Stories Selected:** ${stats.totalStories}\n`;
md += `**Stories Requiring Manual Verification:** ${stats.manualCheckCount}\n\n`;
if (stats.manualCheckCount > 0) {
  md += `> ⚠️ **Attention:** ${stats.manualCheckCount} story/stories scored below the 0.85 confidence threshold. Please cross-check these items against your physical copy of The Hindu before recording.\n\n`;
}
md += `============================================================\n\n`;

for (const [catName, catStories] of Object.entries(categories)) {
  if (catStories.length === 0) continue;
  md += `## ${catName}\n\n`;
  for (let i = 0; i < catStories.length; i++) {
    const s = catStories[i];
    const badge = s.needsManualCheck ? '⚠️ [MANUAL VERIFICATION REQUIRED]' : '✅ [VERIFIED]';
    md += `### ${i + 1}. ${s.title}\n`;
    md += `*Status:* ${badge} | *Confidence:* ${(s.confidence || 0.95).toFixed(2)}\n\n`;
    if (s.malayalamExplanation) {
      md += `${s.malayalamExplanation}\n\n`;
    } else {
      if (s.whatHappened) md += `**What Happened:** ${s.whatHappened}\n\n`;
      if (s.whyImportant) md += `**Why It Matters:** ${s.whyImportant}\n\n`;
      if (s.examPoints && s.examPoints.length) {
        md += `**Key Exam Points:**\n`;
        s.examPoints.forEach(pt => md += `- ${pt}\n`);
        md += `\n`;
      }
    }
    md += `*Primary Source:* [${s.source || 'The Hindu'}](${s.url || '#'})
`;
    if (s.supportingSources && s.supportingSources.length) {
      md += `*Official/Supporting Sources:*
`;
      s.supportingSources.forEach(src => { md += `  - [${src.source}](${src.url}) - ${src.title}
`; });
    }
    md += `\n---\n\n`;
  }
}

md += `## VOCABULARY\n\n`;
vocabulary.forEach((v, idx) => {
  md += `### ${idx + 1}. ${v.word.toUpperCase()} (${v.partOfSpeech || 'n.'})\n`;
  md += `- **English Meaning:** ${v.englishMeaning}\n`;
  md += `- **Malayalam Meaning:** ${v.malayalamMeaning}\n`;
  if (v.synonyms) md += `- **Synonyms:** ${Array.isArray(v.synonyms) ? v.synonyms.join(', ') : v.synonyms}\n`;
  if (v.antonym) md += `- **Antonym:** ${v.antonym}\n`;
  if (v.exampleSentence) md += `- **Example:** *"${v.exampleSentence}"*\n\n`;
});

md += `============================================================\n\n## PRACTICE MCQs\n\n`;
mcqs.forEach((mcq, idx) => {
  md += `**Q${idx + 1}: ${mcq.question}**\n\n`;
  md += `A. ${mcq.options?.A || ''}\nB. ${mcq.options?.B || ''}\nC. ${mcq.options?.C || ''}\nD. ${mcq.options?.D || ''}\n\n`;
  md += `**Correct Answer:** ${mcq.correctAnswer}\n**Explanation:** ${mcq.explanation}\n\n---\n\n`;
});

md += `============================================================\n\n## YOUTUBE SCRIPT (MALAYALAM VOICE-OVER)\n\n${youtubeScript}\n`;

const fileName = `Daily_Current_Affairs_${dateStr.replace(/[^a-zA-Z0-9]/g, '_')}.md`;
const filePath = `/Users/pious/Documents/personalproject/scrapping/reports/${fileName}`;

return [{
  json: {
    date: dateStr,
    fileName,
    filePath,
    markdownReport: md,
    stats,
    storiesCount: stories.length,
    manualCheckCount: stats.manualCheckCount
  }
}];

const data = $input.first().json || {};
const dateStr = data.date || new Date().toISOString().split('T')[0];
const stats = data.stats || { totalStories: 12, manualCheckCount: 0 };
const manualAlert = stats.manualCheckCount > 0
  ? `⚠️ *Manual verification:* ${stats.manualCheckCount} (Cross-check physical Hindu paper!)`
  : `✅ *Manual verification:* 0 (All verified)`;

const telegramText = 
`📰 *DAILY CURRENT AFFAIRS READY*\n\n` +
`📅 *Date:* ${dateStr}\n` +
`🏛️ *Primary Source:* The Hindu\n\n` +
`📰 *Important stories:* ${stats.totalStories}\n` +
`${manualAlert}\n` +
`📚 *Vocabulary:* 5\n` +
`❓ *MCQs:* 15\n` +
`🎙️ *YouTube script:* Ready\n\n` +
`📁 *Saved File:* \`${data.fileName || 'Daily_Current_Affairs.md'}\`\n\n` +
`_Review report before recording voice-over._`;

return [{
  json: {
    telegramText,
    chatId: "YOUR_TELEGRAM_CHAT_ID",
    parseMode: "Markdown"
  }
}];
